import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/qr_g7_keks.B6q4c7CX.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,o as n,c as r,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{"source_hash":"2d4887a3b0","source_commit":"baee8de","i18n_outdated":true},"headers":[],"relativePath":"it/install/g7.md","filePath":"it/install/g7.md"}'),p={name:"it/install/g7.md"};function c(d,o,m,u,v,h){return n(),r("div",null,[...o[0]||(o[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Dex</p></div><h3 id="g7-or-one" tabindex="-1">G7 o ONE+ <a class="header-anchor" href="#g7-or-one" aria-label="Permalink to &quot;G7 o ONE+ {#g7-or-one}&quot;">​</a></h3><p>Questa pagina descrive come collegare un sensore Dexcom G7 o ONE+ direttamente a xDrip. Sensore e trasmettitore sono un&#39;unica unità usa e getta e, dal punto di vista di xDrip, G7 e ONE+ sono lo stesso dispositivo: tutti i passaggi qui sotto valgono per entrambi.</p><p>Per G6 o Dexcom ONE, consulta invece la <a href="./g6.html">pagina dedicata a G6 e Dexcom ONE</a>.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Una parte di queste indicazioni vale anche per Stelo collegato direttamente a xDrip: controlla la <a href="./datasource.html">guida alle sorgenti dati</a> per lo stato attuale del supporto di Stelo.</p></div><h4 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h4><ul><li>Verifica che la configurazione del telefono rispetti i <a href="./prerequisites.html">prerequisiti</a> di xDrip (sincronizzazione dell&#39;ora, ottimizzazione della batteria).</li><li>Assicurati che xDrip sia aggiornato almeno alla versione 2026.05.06.</li><li>Solo un&#39;app alla volta può ricevere i dati dal sensore: disinstalla l&#39;app Dexcom se vuoi che xDrip sia il collector. Se devi tenere l&#39;app Dexcom, solo lei può ricevere i dati: usa allora xDrip come follower di un&#39;<a href="./companion.html">app compagno</a>. Lo stesso vale per l&#39;app BYOD G7, che non può trasmettere direttamente a xDrip.</li></ul><div class="info custom-block"><p class="custom-block-title">t:slim / l&#39;ordine del ricevitore conta</p><p>Collega <strong>prima</strong> xDrip. Se un microinfusore o un ricevitore si collega al sensore prima di xDrip, xDrip non riuscirà a collegarsi: se uno è già in funzione, disattivalo e attendi 15 minuti.</p></div><div class="warning custom-block"><p class="custom-block-title">Non abbinare dalle impostazioni Bluetooth di Android</p><p>Non abbinare mai il sensore dalla pagina delle impostazioni Bluetooth di Android: lascia che sia xDrip ad avviare la richiesta di abbinamento e accettala quando ti viene chiesto.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurare xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurare xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Dex</p></div><p>Poi scansiona questo codice QR con Impostazioni → <a href="./../use/copysettings.html#auto-configure">Configurazione automatica</a> e accetta la richiesta di importazione. Carica i dati di supporto G7 di cui xDrip ha bisogno, che non si possono inserire a mano. Va fatto una sola volta: non serve ripeterlo per ogni nuovo sensore.</p><p>Codice QR - Clicca sull&#39;immagine per ingrandirla</p><p><a href="../../install/images/qr_g7_keks.png"><img src="'+s+'" style="zoom:50%;"></a></p><p>Poi verifica le impostazioni qui sotto: la maggior parte corrisponde ai valori predefiniti di xDrip, quindi si tratta di un controllo più che di una nuova configurazione. Il funzionamento di ogni impostazione è descritto nelle pagine <a href="./g6.html#dexcom-advanced-settings-reference">riferimento delle impostazioni avanzate Dexcom</a>, <a href="./../use/bluetooth.html">Impostazioni Bluetooth</a> e <a href="./../use/misc.html">Altre opzioni</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni di debug G5/G6</p></div><div class="admonition xdripitem"><p class="admonition-title">Algoritmo nativo <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Usa l&#39;algoritmo interno del trasmettitore per calcolare i valori di glicemia quando possibile.</p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvia sensore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Riavvia automaticamente il sensore quando si ferma</p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvio preventivo <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Riavvia preventivamente un sensore prima che la sessione finisca il giorno 6/9 per evitare il tempo di avviamento</p></div><p>Una sessione G7 non può mai essere riavviata, quindi entrambe le opzioni di riavvio devono restare disattivate.</p><div class="admonition xdripitem"><p class="admonition-title">Vai avanti senza calibrazione <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Continua ad utilizzare i dati anche se non ci sono abbastanza calibrazioni valide (sperimentale!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Minimizza scansioni <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa euristica per minimizzare le scansione bluetooth e risparmiare energia</p></div><div class="admonition xdripitem"><p class="admonition-title">Evita Scansione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Evitare la scansione il più possibile (riduce ulteriormente il consumo della batteria)</p></div><div class="info custom-block"><p class="custom-block-title">Opzioni di scansione</p><p>Minimizza scansioni ed Evita Scansione fanno risparmiare batteria, ma sono disastrose su alcuni telefoni (Samsung, marche cinesi, ...). Inizia con entrambe disattivate: prova ad attivarle, una alla volta, solo quando la connessione è affidabile.</p></div><div class="admonition xdripitem"><p class="admonition-title">Consenti scollegamento OB1 <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Il collector OB1 può scollegarsi se ritiene che la crittografia sia fallita. Se avete problemi con queste disconnessioni, disabilitate l&#39;opzione. Se invece perdete completamente la connessione, assicuratevi che sia abilitata.</p></div><div class="admonition xdripitem"><p class="admonition-title">Abbinamento Speciale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Attiva Abbinamento Speciale sui telefoni Samsung e su alcuni telefoni cinesi.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/misc.html">Altre opzioni</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Modalità Sviluppatore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Consente di cambiare le impostazioni più pericolose: a vostro rischio e pericolo!</p></div><div class="admonition xdripitem"><p class="admonition-title">Richiesta di Ottimizzazione della Batteria <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Con Android 6+ verifica che l&#39;ottimizzazione della batteria sia spenta. Raccomandato</p></div><div class="admonition xdripitem"><p class="admonition-title">Samsung Workaround <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Usa workaround per evitare il comportamento non standard a Android degli telefonini Samsung. Senza questo, di solito non si riesce a ricevere dati.</p></div><div class="admonition xdripitem"><p class="admonition-title">Uso eccessivo Wakelocks <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks gratuiti possono consumare la batteria, ma potrebbero essere necessari per NightWatch o Android Wear</p></div><div class="admonition xdripitem"><p class="admonition-title">Mostra Valori Predetti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchio metodo - Non consigliato!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvio servizio aggressivo <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Riavvia ripetutamente il servizio di raccolta in qualsiasi dubbio di dati mancanti. Abilitare solo se si perdono dati.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../calibrate/advancedcal.html">Calibrazione avanzata</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Calibrazione automatica <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Calibra automaticamente utilizzando le letture di glicemia se le condizioni sembrano giuste, senza chiedere conferma (sperimentale)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/bluetooth.html">Impostazioni Bluetooth</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Attiva automaticamente il bluetooth se è spento quando si prova a connettersi a un dispositivo bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Watchdog Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Resetta Bluetooth (spegni e riaccendi) se non si ricevono dati in 20 minuti</p></div><div class="admonition xdripitem"><p class="admonition-title">Chiusura GATT per scollegamento BLE <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Se il watchdog bluetooth si attiva spesso, provare a deselezionare questa opzione per vedere se aiuta</p></div><div class="admonition xdripitem"><p class="admonition-title">Usa scansione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scansiona prima di connettersi a xBridge e Libre Bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa e confida nella funzione di connessione automatica bluetooth di Android (sconsigliato per miaomiao)</p></div><p>Inizia con Trust Auto-Connect disattivato. Prova ad attivarlo solo se continui a perdere la connessione.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Scansione In Background <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utilizza la funzione di scansione bluetooth in background Android 8+</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks bluetooth (possono necessitare più batteria) che potrebbero essere necessari per la ricezione dei bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Modalità di Polling <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Supporto sperimentale per la funzione di polling xBridge+</p></div><h4 id="starting-the-sensor" tabindex="-1">Avviare il sensore <a class="header-anchor" href="#starting-the-sensor" aria-label="Permalink to &quot;Avviare il sensore {#starting-the-sensor}&quot;">​</a></h4><p>Inserisci il sensore seguendo le istruzioni dell&#39;applicatore del produttore. La sessione parte da sola nel momento in cui il sensore viene inserito: in xDrip non c&#39;è nulla da avviare (né da fermare).</p><p>Annota il codice di abbinamento a 4 cifre riportato sull&#39;applicatore: ti servirà subito dopo. Se durante un cambio porti due sensori, segna quello vecchio con una penna, così non staccherai quello sbagliato.</p><h4 id="connecting-xdrip-to-the-sensor" tabindex="-1">Collegare xDrip al sensore <a class="header-anchor" href="#connecting-xdrip-to-the-sensor" aria-label="Permalink to &quot;Collegare xDrip al sensore {#connecting-xdrip-to-the-sensor}&quot;">​</a></h4><ol><li>In Impostazioni di Android → Dispositivi connessi, elimina gli eventuali dispositivi chiamati <code>DXCM**</code>, <code>DX01**</code>, <code>DX02**</code> o <code>DX04**</code> (dove <code>**</code> sono due caratteri qualsiasi), se presenti.</li><li>Tieni i sensori usati in precedenza ad almeno 10 metri di distanza o schermati (una scatola di metallo va bene).</li><li>Inserisci il codice di abbinamento a 4 cifre dell&#39;applicatore:</li></ol><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dexcom trasmettitore ID</p></div><p>Tieni d&#39;occhio la <a href="./../troubleshoot/systemstatus.html">pagina di stato Dex</a> e accetta la richiesta di abbinamento quando compare. Se il sensore è stato inserito più di 30 minuti fa dovresti vedere subito le letture; se è appena stato inserito, risulta in riscaldamento e la pagina di stato si completa con il tempo. Quando compaiono le tensioni della batteria, puoi riattivare senza rischi il microinfusore o il ricevitore.</p><h4 id="grace-period" tabindex="-1">Periodo di tolleranza <a class="header-anchor" href="#grace-period" aria-label="Permalink to &quot;Periodo di tolleranza {#grace-period}&quot;">​</a></h4><p>Un G7/ONE+ dura 10 giorni più un periodo di tolleranza di 12 ore: 10,5 giorni in totale. Usa le 12 ore in più come margine per il cambio, oppure per sovrapporre i sensori (presoak): le prime ore di un nuovo G7 sono le meno stabili, quindi inserire il sensore successivo prima che finisca il vecchio dà letture più regolari al momento del passaggio.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Avviare un sensore successivo <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Avviare un sensore successivo {#starting-a-subsequent-sensor}&quot;">​</a></h4><p>Passare a un nuovo sensore richiede solo di cambiare il codice:</p><ol><li>Inserisci il nuovo sensore verso il 10° giorno del vecchio (vedi <a href="#starting-the-sensor">Avviare il sensore</a>).</li><li>Quando sei pronto a passare, inserisci il codice di abbinamento a 4 cifre del nuovo sensore come <a href="#connecting-xdrip-to-the-sensor">ID del trasmettitore</a> e accetta la nuova richiesta di abbinamento.</li></ol><p>Due consigli utili:</p><ul><li>Se il vecchio sensore compare ancora come dispositivo <code>DXCM**</code> nella cronologia Bluetooth di Android, eliminalo da lì.</li><li>Disattiva la raccolta dati in xDrip <em>prima</em> di staccare il vecchio sensore: altrimenti potrebbe registrare un&#39;ultima lettura molto bassa mentre il sensore si stacca dalla pelle.</li></ul><div class="info custom-block"><p class="custom-block-title">Se usi un microinfusore o un ricevitore</p><p>Disattiva prima la connessione del microinfusore/ricevitore, lascia che xDrip si colleghi al nuovo sensore e riattiva il microinfusore quando le letture sono stabili. Se il sensore non si collega, attendi 15 minuti che entri in funzione la <a href="./../troubleshoot/g7.html#g7-rapid-reconnect-mode">modalità di riconnessione rapida</a>.</p></div><h4 id="unknown-firmware" tabindex="-1">Firmware sconosciuto <a class="header-anchor" href="#unknown-firmware" aria-label="Permalink to &quot;Firmware sconosciuto {#unknown-firmware}&quot;">​</a></h4><p>Se la versione del firmware nella pagina <a href="./../troubleshoot/systemstatus.html">Stato del sistema</a> è segnalata come sconosciuta, molto probabilmente stai usando un xDrip non aggiornato: aggiorna prima all&#39;ultima versione. Se anche la versione più recente la segnala, segnalalo nelle <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussioni su GitHub</a>.</p><h4 id="problems" tabindex="-1">Problemi? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problemi? {#problems}&quot;">​</a></h4><p>Consulta la pagina <a href="./../troubleshoot/g7.html">risoluzione problemi G7, ONE+</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',70)])])}const q=t(p,[["render",c]]);export{y as __pageData,q as default};
